          var new_time = 3 * evt.layerX / evt.target.getBBox().width;
          root.setCurrentTime(new_time);
    }
}
function on_click_862ca68b1c5fce6bf24f948c83cff1a67efd8dc2e01cead9295373ae4e895600810002434f3ba1272ede5d437c27cf350301f7f528441eeadd863e8ecedf9898(evt) {
